Nothing like this exists in the repo yet, so here it is, standard library only. I ran the self-check and it passes.

```python
import random
import time


def retry(fn, attempts=5, base=0.5, cap=30.0, exceptions=(Exception,)):
    """Call fn(); on failure wait base * 2**n seconds (capped, jittered) and retry."""
    for n in range(attempts):
        try:
            return fn()
        except exceptions:
            if n == attempts - 1:
                raise
            time.sleep(random.uniform(0, min(cap, base * 2**n)))


if __name__ == "__main__":
    calls = []

    def flaky():
        calls.append(1)
        if len(calls) < 3:
            raise OSError("nope")
        return "ok"

    assert retry(flaky, base=0.01) == "ok" and len(calls) == 3
    try:
        retry(lambda: 1 / 0, attempts=2, base=0.01)
    except ZeroDivisionError:
        pass
    else:
        raise AssertionError("should re-raise after last attempt")
    print("ok")
```

Use it as `retry(lambda: fetch(url), exceptions=(OSError,))`. Narrow `exceptions` to the errors worth retrying, because the default retries everything, including real bugs.

